-- Financeiro, ajuste 14 (Karol, 03/11/2026): refaz o repasse de fim de mês nov/25–out/26 agora que as parcelas do empréstimo saem da conta PJ.
-- Mesma regra do ajuste 5: conta PJ zera todo fim de mês (out/26 fica com R$0,49); mês negativo vira aporte seu.
delete from public.fin_lancamentos where origem='manual' and origem_id ~ '^(repasse|aporte)-20(25-1[12]|26-(0[1-9]|10))$';
) v on conflict do nothing;
select json_agg(json_build_object('id',origem_id,'v',valor_bruto) order by origem_id) from public.fin_lancamentos where origem_id ~ '^(repasse|aporte)-';
